CREATE TABLE IF NOT EXISTS math_explanations (id TEXT PRIMARY KEY, problem_id TEXT NOT NULL REFERENCES math_problems(id), verification_report_id TEXT NOT NULL REFERENCES math_verification_reports(id), candidate_solution_result_id TEXT NOT NULL REFERENCES math_candidate_solution_results(id), user_id TEXT NOT NULL, request_id TEXT NOT NULL, input_source_revision INTEGER NOT NULL, input_hash TEXT NOT NULL, provider TEXT NOT NULL, model_name TEXT NOT NULL, model_version TEXT NOT NULL, prompt_id TEXT NOT NULL, prompt_version TEXT NOT NULL, prompt_content_hash TEXT NOT NULL, prompt_created_at TEXT NOT NULL, schema_version TEXT NOT NULL, teaching_profile_hash TEXT NOT NULL, status TEXT NOT NULL, explanation_input_json TEXT NOT NULL, raw_model_response_json TEXT, validated_explanation_json TEXT, warnings_json TEXT NOT NULL DEFAULT '[]', errors_json TEXT NOT NULL DEFAULT '[]', input_tokens INTEGER, output_tokens INTEGER, estimated_cost REAL, duration_ms INTEGER, cache_hit INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(verification_report_id,input_hash,provider,model_name,prompt_version,schema_version,teaching_profile_hash));
CREATE INDEX IF NOT EXISTS idx_math_explanations_current ON math_explanations(problem_id,input_source_revision,created_at);
CREATE INDEX IF NOT EXISTS idx_math_explanations_request ON math_explanations(user_id,request_id);
CREATE TRIGGER IF NOT EXISTS math_explanations_no_update BEFORE UPDATE ON math_explanations BEGIN SELECT RAISE(ABORT,'math_explanations_are_immutable'); END;
CREATE TRIGGER IF NOT EXISTS math_explanations_no_delete BEFORE DELETE ON math_explanations BEGIN SELECT RAISE(ABORT,'math_explanations_are_immutable'); END;
